// Package mailnotify ports the host and guest mail builders of
// App/app/mail_notify.py. Output is byte-identical to the Python builders
// (subject, plain text and HTML); testdata/reminders_golden.json is generated by
// App/scripts/go_mailnotify_golden.py and replayed by the tests.
//
// Reusable API for further builders (build_fee_update and later):
//   - Content: what every builder returns (Subject, Text, HTML).
//   - Shell / ShellParams: wraps block rows in the branded card. Blocks are
//     rendered by the Block* helpers and Button; pass them as ShellParams.Blocks.
//   - Footer lines (ShellParams.FooterLines and the text part) are a string, a
//     []FooterLink (channels joined by " \u00b7 "), or a *FooterSentence (text with
//     %(name)s link markers). GuestFooterLines builds the guest footer from a Host.
//   - GuestText / HostText: catalogue lookups with the Python fallbacks
//     (missing key -> English -> key itself; %-format failure -> raw text).
//   - GuestLanguage / HostLanguage: normalise_language for each audience.
//   - SetGuestLanguages: the UBYHOST_GUEST_LANGS env value. Call once at startup
//     (the default is the Python default "en,cs"). Not safe to change concurrently.
//
// publicBaseURL is config.PUBLIC_BASE_URL without a trailing slash; the logo is
// served from it. The caller reads it from the environment.
package mailnotify

import (
	"regexp"
	"strconv"
	"strings"
)

// Brand tokens, copied from static/tokens.css and App/app/mail_notify.py.
const (
	LogoPath     = "/static/ubyhost-logo.jpg"
	LogoWidth    = 180
	Ink          = "#20201e"
	InkSecondary = "#50504c"
	InkMuted     = "#73736e"
	Canvas       = "#f7f7f5"
	Surface      = "#ffffff"
	Line         = "#e4e4e1"
	BrandAction  = "#ad4942"
	BrandInk     = "#963e38"
	BrandSoft    = "#f9e9e7"

	Font     = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif"
	MonoFont = "ui-monospace,SFMono-Regular,Menlo,Consolas,'Liberation Mono',monospace"

	FooterSeparator = " \u00b7 "
)

// preheaderSpacer is PREHEADER_SPACER: 40 repeats of figure space, zero-width
// no-break space and combining grapheme joiner.
var preheaderSpacer = strings.Repeat("\u2007\ufeff\u034f", 40)

var escaper = strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&quot;", "'", "&#x27;")

// Esc is _esc: html.escape of one interpolated value for the HTML part.
func Esc(s string) string { return escaper.Replace(s) }

// Content is the result of a builder: the three parts of one message.
type Content struct {
	Subject string
	Text    string
	HTML    string
}

// FooterLink is one tappable channel in a footer line (_FooterLink).
type FooterLink struct {
	Label string
	Href  string
}

// FooterLinkRef is one named link inside a FooterSentence.
type FooterLinkRef struct {
	Label string
	Href  string
}

// FooterSentence is _FooterSentence: text holding %(name)s markers, and the
// links those names stand for. A missing name renders as an empty link, as in Python.
type FooterSentence struct {
	Text  string
	Links map[string]FooterLinkRef
}

var footerMarker = regexp.MustCompile(`%\(([\p{L}\p{N}_]+)\)s`)

type sentencePart struct {
	text   string
	isLink bool
	ref    FooterLinkRef
}

func (s *FooterSentence) parts() []sentencePart {
	var out []sentencePart
	pos := 0
	for _, m := range footerMarker.FindAllStringSubmatchIndex(s.Text, -1) {
		out = append(out, sentencePart{text: s.Text[pos:m[0]]})
		out = append(out, sentencePart{isLink: true, ref: s.Links[s.Text[m[2]:m[3]]]})
		pos = m[1]
	}
	out = append(out, sentencePart{text: s.Text[pos:]})
	return out
}

// Plain is the text-part rendering: "label (URL)", or the bare URL when the label is empty.
func (s *FooterSentence) Plain() string {
	var b strings.Builder
	for _, p := range s.parts() {
		if !p.isLink {
			b.WriteString(p.text)
			continue
		}
		if p.ref.Label != "" {
			b.WriteString(p.ref.Label + " (" + p.ref.Href + ")")
		} else {
			b.WriteString(p.ref.Href)
		}
	}
	return b.String()
}

// HTML is the HTML-part rendering: each link becomes an anchor.
func (s *FooterSentence) HTML() string {
	var b strings.Builder
	for _, p := range s.parts() {
		if !p.isLink {
			b.WriteString(Esc(p.text))
			continue
		}
		label := p.ref.Label
		if label == "" {
			label = p.ref.Href
		}
		b.WriteString(`<a href="` + Esc(p.ref.Href) + `" style="color:` + InkSecondary +
			`;text-decoration:underline;">` + Esc(label) + `</a>`)
	}
	return b.String()
}

// FooterText is _footer_text: the plain-text mirror of a footer. Strings pass
// through unescaped.
func FooterText(lines []any) []string {
	out := make([]string, 0, len(lines))
	for _, line := range lines {
		switch v := line.(type) {
		case []FooterLink:
			labels := make([]string, 0, len(v))
			for _, l := range v {
				labels = append(labels, l.Label)
			}
			out = append(out, strings.Join(labels, FooterSeparator))
		case *FooterSentence:
			out = append(out, v.Plain())
		case string:
			out = append(out, v)
		}
	}
	return out
}

// footerLineHTML is _footer_line_html.
func footerLineHTML(line any) string {
	switch v := line.(type) {
	case *FooterSentence:
		return v.HTML()
	case []FooterLink:
		anchors := make([]string, 0, len(v))
		for _, l := range v {
			anchors = append(anchors, `<a href="`+Esc(l.Href)+`" style="color:`+InkSecondary+
				`;text-decoration:underline;">`+Esc(l.Label)+`</a>`)
		}
		return strings.Join(anchors, FooterSeparator)
	case string:
		return Esc(v)
	}
	return ""
}

// ShellParams are the arguments of _shell.
type ShellParams struct {
	PublicBaseURL string   // config.PUBLIC_BASE_URL, no trailing slash
	Lang          string   // written raw into <html lang>, as the Python does
	Title         string   // property name in the reminder builders
	Preheader     string   // inbox snippet; empty means no preheader div
	Blocks        []string // rows from the Block* helpers
	FooterLines   []any    // see FooterText
}

// Shell is _shell: the branded light-mode card around the blocks.
func Shell(p ShellParams) string {
	var footer strings.Builder
	for i, line := range p.FooterLines {
		if i > 0 {
			footer.WriteString(`<div style="padding:4px 0 0 0;">` + footerLineHTML(line) + `</div>`)
		} else {
			footer.WriteString(`<div>` + footerLineHTML(line) + `</div>`)
		}
	}
	preheaderHTML := ""
	if p.Preheader != "" {
		preheaderHTML = `<div style="display:none;font-size:1px;line-height:1px;max-height:0;` +
			`max-width:0;opacity:0;overflow:hidden;mso-hide:all;">` + Esc(p.Preheader) + preheaderSpacer + `</div>`
	}
	logo := p.PublicBaseURL + LogoPath
	width := strconv.Itoa(LogoWidth)
	return `<!doctype html>
<html lang="` + Esc(p.Lang) + `">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light only">
<title>` + Esc(p.Title) + `</title>
</head>
<body style="margin:0;padding:0;background:` + Canvas + `;">
` + preheaderHTML + `
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:` + Canvas + `;border-collapse:collapse;">
<tr><td align="center" style="padding:28px 12px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:` + Surface + `;border:1px solid ` + Line + `;border-radius:14px;border-collapse:separate;">
<tr><td style="padding:28px 24px 0 24px;">
<img src="` + Esc(logo) + `" width="` + width + `" alt="UbyHost" style="display:block;border:0;outline:none;text-decoration:none;width:` + width + `px;max-width:100%;height:auto;">
</td></tr>
` + strings.Join(p.Blocks, "") + `
<tr><td style="padding:28px 24px 28px 24px;">
<div style="border-top:1px solid ` + Line + `;padding:16px 0 0 0;font:400 13px/1.6 ` + Font + `;color:` + InkMuted + `;">
` + footer.String() + `
</div>
</td></tr>
</table>
</td></tr>
</table>
</body>
</html>
`
}

// Button is _button: a bordered-cell button, 48px tall and clickable in Outlook.
func Button(url, label string) string {
	return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" ` +
		`style="border-collapse:separate;margin:0 0 8px 0;">` +
		`<tr><td style="background:` + BrandAction + `;border-radius:8px;` +
		`padding:14px 24px;">` +
		`<a href="` + Esc(url) + `" style="display:block;padding:0;` +
		`font:600 16px/20px ` + Font + `;color:` + Surface + `;text-decoration:none;">` +
		Esc(label) + `</a>` +
		`</td></tr></table>`
}

// BlockHeading is _block_heading (the H1 row).
func BlockHeading(text string) string {
	return `<tr><td style="padding:20px 24px 0 24px;">` +
		`<h1 style="margin:0;font:600 22px/1.3 ` + Font + `;color:` + Ink + `;">` +
		Esc(text) + `</h1></td></tr>`
}

// BlockParagraph is _block_paragraph with the default size (16px, or 14px when muted).
func BlockParagraph(text string, muted bool) string {
	return BlockParagraphSized(text, muted, 0)
}

// BlockParagraphSized is _block_paragraph; size 0 means the default.
func BlockParagraphSized(text string, muted bool, size int) string {
	colour := InkSecondary
	if muted {
		colour = InkMuted
	}
	if size == 0 {
		size = 16
		if muted {
			size = 14
		}
	}
	return `<tr><td style="padding:12px 24px 0 24px;">` +
		`<p style="margin:0;font:400 ` + strconv.Itoa(size) + `px/1.6 ` + Font + `;color:` + colour + `;">` +
		Esc(text) + `</p></td></tr>`
}

// BlockSection is _block_section: a bold label over a body paragraph.
func BlockSection(label, body string) string {
	return `<tr><td style="padding:24px 24px 0 24px;">` +
		`<div style="font:600 14px/1.4 ` + Font + `;color:` + Ink + `;padding:0 0 8px 0;">` +
		Esc(label) + `</div>` +
		`<p style="margin:0;font:400 15px/1.6 ` + Font + `;color:` + InkSecondary + `;">` +
		Esc(body) + `</p></td></tr>`
}

// BlockNote is _block_note: the tinted box with a label and pre-wrapped body.
func BlockNote(label, body string) string {
	return `<tr><td style="padding:24px 24px 0 24px;">` +
		`<div style="background:` + BrandSoft + `;border-radius:10px;padding:16px 18px;">` +
		`<div style="font:600 14px/1.4 ` + Font + `;color:` + BrandInk + `;padding:0 0 8px 0;">` +
		Esc(label) + `</div>` +
		`<div style="font:400 14px/1.6 ` + Font + `;color:` + Ink + `;` +
		`white-space:pre-wrap;word-break:break-word;">` + Esc(body) + `</div>` +
		`</div></td></tr>`
}

// BlockFact is _block_fact: a label and one value.
func BlockFact(label, value string) string {
	return `<tr><td style="padding:20px 24px 0 24px;">` +
		`<div style="font:600 14px/1.4 ` + Font + `;color:` + Ink + `;padding:0 0 6px 0;">` +
		Esc(label) + `</div>` +
		`<div style="font:400 15px/1.5 ` + Font + `;color:` + Ink + `;">` + Esc(value) + `</div>` +
		`</td></tr>`
}

// BlockButton is _block_button.
func BlockButton(url, label string) string {
	return `<tr><td style="padding:8px 24px 0 24px;">` + Button(url, label) + `</td></tr>`
}

// PanelRow is one label/value row of a BlockPanel. Mono prints the value in a
// monospace face, for values a guest copies by hand (IBAN, VS, reference).
type PanelRow struct {
	Label string
	Value string
	Mono  bool
}

// PanelAction is the optional button inside a BlockPanel.
type PanelAction struct {
	URL   string
	Label string
}

// BlockPanel is _block_panel: a bordered sub-card with a title, rows, an optional
// muted note and at most one button.
func BlockPanel(title string, rows []PanelRow, action *PanelAction, note string) string {
	rendered := make([]string, 0, len(rows))
	for _, row := range rows {
		valueStyle := `font:600 15px/1.5 ` + Font + `;color:` + Ink + `;`
		if row.Mono {
			valueStyle = `font:400 14px/1.5 ` + MonoFont + `;color:` + Ink + `;word-break:break-all;`
		}
		rendered = append(rendered, "<tr>"+
			`<td style="padding:0 12px 8px 0;font:400 13px/1.5 `+Font+`;color:`+InkMuted+
			`;vertical-align:top;white-space:nowrap;">`+Esc(row.Label)+`</td>`+
			`<td style="padding:0 0 8px 0;text-align:right;`+valueStyle+
			`vertical-align:top;">`+Esc(row.Value)+`</td>`+
			"</tr>")
	}
	parts := []string{
		`<div style="font:600 15px/1.4 ` + Font + `;color:` + Ink + `;padding:0 0 10px 0;">` + Esc(title) + `</div>`,
		`<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;">` +
			strings.Join(rendered, "") + `</table>`,
	}
	if note != "" {
		parts = append(parts, `<div style="font:400 13px/1.6 `+Font+`;color:`+InkMuted+
			`;padding:8px 0 0 0;">`+Esc(note)+`</div>`)
	}
	if action != nil {
		parts = append(parts, `<div style="padding:14px 0 0 0;">`+Button(action.URL, action.Label)+`</div>`)
	}
	return `<tr><td style="padding:24px 24px 0 24px;">` +
		`<div style="background:` + Canvas + `;border:1px solid ` + Line + `;` +
		`border-radius:12px;padding:18px 20px;">` + strings.Join(parts, "") + `</div></td></tr>`
}

// BlockLink is _block_link: the full address under a button, for clients that break it.
func BlockLink(url, label string) string {
	return `<tr><td style="padding:14px 24px 0 24px;">` +
		`<div style="font:400 13px/1.6 ` + Font + `;color:` + InkMuted + `;">` + Esc(label) + `</div>` +
		`<div style="font:400 13px/1.6 ` + Font + `;color:` + InkSecondary + `;word-break:break-all;">` +
		`<a href="` + Esc(url) + `" style="color:` + BrandAction + `;text-decoration:underline;">` +
		Esc(url) + `</a></div></td></tr>`
}

// BlockQuietLink is _block_quiet_link: a labelled underlined link with no button.
func BlockQuietLink(url, label string) string {
	return `<tr><td style="padding:14px 24px 0 24px;">` +
		`<div style="font:400 14px/1.5 ` + Font + `;color:` + InkSecondary + `;">` +
		`<a href="` + Esc(url) + `" style="color:` + BrandAction + `;text-decoration:underline;">` +
		Esc(label) + `</a></div></td></tr>`
}

// GuestBlocks is _guest_blocks: heading, intro paragraph, button, then extras.
func GuestBlocks(heading, intro, actionURL, actionLabel string, extra []string) []string {
	blocks := []string{
		BlockHeading(heading),
		BlockParagraph(intro, false),
		BlockButton(actionURL, actionLabel),
	}
	return append(blocks, extra...)
}
